def get_user_input(prompt):
    """Get user input and validate it."""
    while True:
        user_input = input(prompt)
        if user_input.strip() == "":
            print("Please enter a non-empty value.")
        else:
            return user_input

def calculate_score(answers):
    """Calculate the user's score based on their answers."""
    score = 0
    for i, answer in enumerate(answers):
        if answer == "correct":
            score += 5
        elif answer == "incorrect":
            score -= 2
        else:
            print(f"Invalid answer for question {i+1}. Please enter 'correct' or 'incorrect'.")
            return score
    return score

def main():
    print("Welcome to the quiz! Answer 'correct' or 'incorrect' for each question.")
    answers = []

    for i in range(5):
        prompt = f"Question {i+1}: "
        answer = get_user_input(prompt)
        answers.append(answer)

    score = calculate_score(answers)
    print(f"You scored {score} out of 5.")

if __name__ == "__main__":
    main()
```

This program defines three functions: `get_user_input`, which gets user input and validates it; `calculate_score`, which calculates the user's score based on their answers; and `main`, which calls the other two functions and displays the user's score. The program then enters a loop that asks the user five questions and keeps track of their score.
